-- Ejecutar después de 01_schema_banco_sangre_organos.sql:
--   sudo -u postgres psql < 02_inserts_banco_sangre_organos.sql
-- El script corre en una sola transacción: si algo falla, no se inserta nada.
-- Para recargar desde cero, vuelva a correr 01 (borra y crea la base) y luego 02 en adelante.
--
-- Usuarios de prueba: contraseña 'Demo2026!' (hash bcrypt en password_hash).
